#!/usr/bin/env python3
"""Install test-only JSONL audit read synchronization; no service actions.

Requires the existing native-schema Shadow update. Only tests and MANIFEST are
changed. Runtime code, audit writers, schema validators and model requests are
byte-identical. Does not contact services or read production/account files.
"""
from __future__ import annotations
import argparse
import base64
from contextlib import contextmanager
import datetime as dt
import fcntl
import hashlib
import json
import os
from pathlib import Path
import stat
import sys
import tempfile
import zlib

PAYLOAD = {'tests/audit_support.py': '', 'tests/test_bundle.py': '', 'tests/test_native_schema.py': '', 'MANIFEST.sha256': ''}
BEFORE = {'tests/audit_support.py': None, 'tests/test_bundle.py': '0d22ebb5ad9ba788605dfbe7ef77f2050c365ab207109e6a8e015186ea95daa5', 'tests/test_native_schema.py': '00eedee5fea1d77ad36786626580dd123e86cbc062caa8dc59e4b1ed1a2b1d82', 'MANIFEST.sha256': 'c2d06c52bc0a9633b6f6ede492c6165cc86a83bcd165fa0cbdf7a5c189aef55e'}
AFTER = {'tests/audit_support.py': 'fab7bf3ebfdd0a92ed3fcc9ebe98152571ec5f3e897d57d1bdbc27e6d8b7ef33', 'tests/test_bundle.py': '1a7a2378ea2ac21dbb10a4f6e647cd0af50acd4e0da6725383cc08419ff6b1ce', 'tests/test_native_schema.py': 'c25685f822b34057e4f1527fa9b2e3ee33f4def6e21bb59ac90a55aca20cb7e5', 'MANIFEST.sha256': '162d0217b44da7a0fa60cc59e32f711ed7467941cb02873c1ee2e7be13c713e7'}
DEFAULT = '/var/lib/jenkins/tomod/ops/local-llm-path-benchmark'
LOCKS = ('.verified-workflow.lock', '.benchmark.lock')

class Refuse(RuntimeError): pass

def sha(data: bytes) -> str:return hashlib.sha256(data).hexdigest()

def plain_path(p: Path) -> None:
    for part in (p,*p.parents):
        if part.is_symlink():raise Refuse('Symlink refused: '+str(part))

def payload() -> dict[str,bytes]:
    out={k:zlib.decompress(base64.b64decode(v)) for k,v in PAYLOAD.items()}
    if set(out)!=set(AFTER):raise Refuse('Payload membership mismatch')
    for name,data in out.items():
        if sha(data)!=AFTER[name]:raise Refuse('Payload checksum mismatch: '+name)
    return out

@contextmanager
def locks(target:Path,create:bool):
    fds=[]
    try:
        for name in LOCKS:
            p=target/name;plain_path(p)
            if not p.exists() and not create:continue
            fd=os.open(p,os.O_RDWR|os.O_NOFOLLOW|(os.O_CREAT if create else 0),0o600);fds.append(fd)
            if not stat.S_ISREG(os.fstat(fd).st_mode):raise Refuse('Lock is not regular')
            try:fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)
            except BlockingIOError:raise Refuse('Workflow/recovery is active; no update') from None
        yield
    finally:
        for fd in reversed(fds):os.close(fd)

def inspect(target:Path)->str:
    plain_path(target)
    if target.name!='local-llm-path-benchmark' or target.parent.name!='ops' or not target.is_dir():
        raise Refuse('Expected an existing ops/local-llm-path-benchmark directory')
    private=target/'.state';plain_path(private)
    if private.exists():
        for p in private.glob('*/journal.json'):
            plain_path(p)
            if not p.is_file() or p.stat().st_size>2*1024*1024:raise Refuse('Invalid recovery journal')
            if json.loads(p.read_text()).get('cleanup_pass') is not True:
                raise Refuse('Unresolved recovery; this update does not change lifecycle logic: '+str(p.parent))
    manifest=target/'MANIFEST.sha256';plain_path(manifest)
    h=sha(manifest.read_bytes())
    mode='before' if h==BEFORE['MANIFEST.sha256'] else 'after' if h==AFTER['MANIFEST.sha256'] else None
    if mode is None:raise Refuse('Unrecognized harness manifest; do not overwrite unknown edits')
    seen=set()
    for line in manifest.read_text().splitlines():
        expected,name=line.split('  ',1)
        if name in seen or Path(name).is_absolute() or '..' in Path(name).parts:raise Refuse('Invalid manifest path')
        seen.add(name);p=target/name;plain_path(p)
        if not p.is_file() or sha(p.read_bytes())!=expected:raise Refuse('Manifest mismatch: '+name)
    for name,expected in (BEFORE if mode=='before' else AFTER).items():
        p=target/name;plain_path(p)
        if expected is None:
            if p.exists():raise Refuse('Would overwrite an unmanaged file: '+name)
        elif not p.is_file() or sha(p.read_bytes())!=expected:
            raise Refuse('Unexpected managed file: '+name)
    return mode

def write_atomic(p:Path,data:bytes,metadata=None):
    plain_path(p);plain_path(p.parent)
    if not p.parent.is_dir():raise Refuse('Expected existing parent directory')
    fd,tmp=tempfile.mkstemp(prefix='.audit-reader-',dir=p.parent)
    try:
        with os.fdopen(fd,'wb') as f:
            f.write(data);f.flush();os.fsync(f.fileno())
            os.fchmod(f.fileno(),stat.S_IMODE(metadata.st_mode) if metadata else 0o600)
            if metadata and (metadata.st_uid,metadata.st_gid)!=(os.geteuid(),os.getegid()):
                os.fchown(f.fileno(),metadata.st_uid,metadata.st_gid)
        os.replace(tmp,p)
    finally:
        if os.path.exists(tmp):os.unlink(tmp)

def update(target:Path,apply:bool=False):
    data=payload();plain_path(target)
    if not target.is_dir():raise Refuse('Target is missing')
    with locks(target,apply):
        mode=inspect(target)
        result={'pass':True,'mode':'already_current' if mode=='after' else 'apply' if apply else 'check_only',
                'managed_files_changed':0,'service_actions':0,'production_files_written':0,
                'account_files_read':0,'existing_snapshot_changes':0,'runtime_mode_changed':False,'runtime_files_changed':0,'schema_rules_changed':False}
        if mode=='after' or not apply:return result
        tag=dt.datetime.now(dt.timezone.utc).strftime('%Y%m%d-%H%M%S-%f')
        backup=target/'backups'/('audit-reader-'+tag);plain_path(backup);backup.mkdir(parents=True,mode=0o700)
        old={};metadata={};written=[]
        for name in data:
            p=target/name;plain_path(p)
            old[name]=p.read_bytes() if p.exists() else None
            metadata[name]=p.stat() if p.exists() else None
            if (sha(old[name]) if old[name] is not None else None)!=BEFORE[name]:raise Refuse('Concurrent tool edit: '+name)
            if old[name] is not None:
                q=backup/name;q.parent.mkdir(parents=True,exist_ok=True);q.write_bytes(old[name]);q.chmod(0o600)
        (backup/'new-file-paths.json').write_text(json.dumps([n for n,v in old.items() if v is None]))
        try:
            for name in sorted(data,key=lambda n:(n=='MANIFEST.sha256',n)):
                p=target/name;plain_path(p)
                current=p.read_bytes() if p.exists() else None
                if (sha(current) if current is not None else None)!=BEFORE[name]:raise Refuse('Concurrent tool edit: '+name)
                write_atomic(p,data[name],metadata[name]);written.append(name)
            if inspect(target)!='after':raise Refuse('Post-install checksum mismatch')
        except BaseException:
            failed=[]
            for name in reversed(written):
                p=target/name
                try:
                    plain_path(p)
                    if not p.is_file() or sha(p.read_bytes())!=AFTER[name]:raise Refuse('Concurrent edit during rollback')
                    if old[name] is None:p.unlink()
                    else:write_atomic(p,old[name],metadata[name])
                except Exception:failed.append(name)
            if failed:
                (backup/'ROLLBACK_FAILED.json').write_text(json.dumps({'paths':failed}))
                raise Refuse('Rollback incomplete; preserve backup and stop tests') from None
            raise
        result.update(managed_files_changed=len(data),backup=str(backup))
        (backup/'update-result.json').write_text(json.dumps(result,indent=2)+'\n')
        return result

def main():
    ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('--target',default=DEFAULT)
    group=ap.add_mutually_exclusive_group(required=True)
    group.add_argument('--check-only',action='store_true');group.add_argument('--apply',action='store_true')
    a=ap.parse_args();os.umask(0o077)
    print(json.dumps(update(Path(a.target).absolute(),a.apply),ensure_ascii=False,indent=2));return 0

if __name__=='__main__':
    try:raise SystemExit(main())
    except (Refuse,OSError,ValueError) as e:print('[REFUSED]',str(e),file=sys.stderr);raise SystemExit(1)
    except KeyboardInterrupt:print('[INTERRUPTED] Review backup/manifest; no service actions',file=sys.stderr);raise SystemExit(130)
